betting_card_runners_display_query#ee702:
query BettingCardRunnersDisplay($urn: [URN!]!, $requestForExc: Boolean!, $requestForSbk: Boolean!, $preferences: LayoutPreferencesInput, $productExclusions: [ProductExclusion!], $experiments: [ExperimentsInput!]) @preferences(preferences: $preferences) @productExclusions(productExclusions: $productExclusions) @experiments(experiments: $experiments) {
  Cards(cardsURN: $urn) {
    __typename
    ... on MarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on MarketExtendedCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on EventMarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on RaceMarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
  }
}

fragment displayRunners on DisplayRunners {
  exchange @include(if: $requestForExc) {
    runners {
      runnerURN
    }
  }
  sportsbook @include(if: $requestForSbk) {
    runners {
      runnerURN
    }
  }
}

